clearScene();setBig(null);
setEq("$$\\nabla_\\theta V=\\mathbb{E}_\\tau\\Big[\\Big(\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t|s_t)\\Big)R(\\tau)\\Big]$$","top");
note("这还是个期望",640,310,"y lg");
setCap("式子有了。<b>但期望不能直接算</b> —— 轨迹有指数多条。");

clearScene();setEq(null);
setBig("那就还是算不了","期望和求和不都一样吗");
setCap("不一样。<b>求和必须穷举，期望可以抽样</b> —— 这正是上一集那一步的全部价值。");

clearScene();setBig(null);
setEq("$$\\hat g=\\frac{1}{m}\\sum_{i=1}^{m}\\Big(\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a^{(i)}_t|s^{(i)}_t)\\Big)R(\\tau^{(i)})$$","top");
note("跑 m 条轨迹，取平均",640,320,"g lg");
setCap("<b>REINFORCE</b>：跑 m 条轨迹，每条算一次，平均 —— 就是梯度的无偏估计。");

clearScene();setBig(null);setEq(null);
note("score 指方向",400,280,"b lg");
note("回报定大小和正负",880,280,"y lg");
note("好 → 加大这些动作的概率",640,400,"g lg");
setCap("读法：<b>score 说往哪推，回报说推多少、往哪边推</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"无偏",sub:"E[ĝ] = ∇V",state:"on"},
  {label:"无模型",sub:"只要能跑回合",state:"on"},
  {label:"方差",sub:"大到常常没法直接用",state:"dead"}]});
note("无偏 ≠ 可用",640,420,"r");
setCap("<b>指名反驳</b>：期望可以抽样。<b>但无偏不等于可用</b> —— 方差是下一个问题。");

clearScene();setBig(null);
setEq("$$\\Big(\\textstyle\\sum_{t}\\nabla\\log\\pi_\\theta(a_t|s_t)\\Big)\\Big(\\textstyle\\sum_{t'}r_{t'}\\Big)$$","top");
note("每个 score 乘了全部奖励",640,310,"r lg");
setCap("展开看：<b>第 t 步的 score，乘上了包括 t 之前在内的所有奖励</b>。");

clearScene();setEq(null);
setBig("无偏就行，别的无所谓","反正 E[ĝ] 等于真梯度");
setCap("它确实不影响<b>期望</b> —— <b>但它把方差白白加大了</b>。");

clearScene();setBig(null);
setEq("$$\\mathbb{E}_{a\\sim\\pi_\\theta}\\big[\\nabla_\\theta\\log\\pi_\\theta(a|s)\\big]=\\nabla_\\theta\\textstyle\\sum_a\\pi_\\theta(a|s)=\\nabla_\\theta 1=0$$","top");
note("score 的期望恒为 0",640,320,"g lg");
setCap("关键引理：<b>score function 的期望恒等于 0</b>。三步就能证。");

clearScene();setBig(null);
setEq("$$\\nabla_\\theta V=\\mathbb{E}\\Big[\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t|s_t)\\,G_t\\Big],\\quad G_t=\\textstyle\\sum_{t'\\ge t}r_{t'}$$","top");
note("只乘它之后的回报",640,320,"g lg");
setCap("于是可以<b>把过去的奖励全部删掉</b>：每个 score 只乘 <b>G_t</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"期望",sub:"完全没变",state:"on"},
  {label:"方差",sub:"变小了",state:"on"},
  {label:"代价",sub:"没有",state:"on"}]});
note("这种修改很罕见",640,420,"y");
setCap("<b>指名反驳</b>：无偏不是终点。<b>这是一次不付任何代价的降方差。</b>");

clearScene();setBig(null);setEq(null);
note("动作是实数",640,280,"b lg");
note("π_θ(a|s) 该长什么样",640,350,"y lg");
setCap("整套推导只要求 π_θ <b>可导</b>。<b>那连续动作怎么写？</b>");

clearScene();setEq(null);
setBig("把动作离散化","切成一百格，就变回熟悉的情形了");
setCap("能做，但代价是<b>维数灾难</b> —— 而且你根本不需要这么做。");

clearScene();setBig(null);
setEq("$$\\pi_\\theta(a\\mid s)=\\mathcal{N}\\big(\\mu(s),\\ \\sigma^2\\big),\\qquad \\mu(s)=\\phi(s)^{\\top}\\theta$$","top");
note("均值由参数决定",640,300,"b lg");
note("σ 控制随机性",640,360,"v lg");
setCap("<b>高斯策略</b>：网络输出一个<b>均值</b>，动作从以它为中心的高斯里抽。");

clearScene();setBig(null);
setEq("$$\\nabla_\\theta\\log\\pi_\\theta(a\\mid s)=\\frac{\\big(a-\\mu(s)\\big)\\,\\phi(s)}{\\sigma^2}$$","top");
note("实际动作减去均值",640,300,"g lg");
note("除以 σ² 放大",640,360,"y lg");
setCap("高斯策略的 score：<b>(实际动作 − 均值) × 特征 ÷ σ²</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"连续动作",sub:"抽样即可 · 无需离散化",state:"on"},
  {label:"随机策略",sub:"参数化自带",state:"on"},
  {label:"可导",sub:"唯一的要求",state:"on"}]});
note("三个理由在这里合流",640,420,"y");
setCap("<b>指名反驳</b>：不必离散化。<b>策略梯度里没有 argmax，所以没有要迁就的东西。</b>");
